extern "C" {

ccm_status parking_Vehicle_class(const parking_Vehicle* self, int32_t* result) {
    return bridge::guard([&] {
        const parking::Vehicle* vehicle = bridge::from_handle(self).get();
        if (dynamic_cast<const parking::Car*>(vehicle) != nullptr) {
            *result = 1;
        } else if (dynamic_cast<const parking::Motorcycle*>(vehicle) != nullptr) {
            *result = 2;
        } else {
            *result = 0;
        }
    });
}

