// The C++ of Parking.Car, Parking.Motorcycle, Parking.Vehicle, ported from C# (CodeCoreMorph, D-78).
#include "vehicle.hpp"

#include <cctype>
#include <string>

#include "codecoremorph_exceptions.hpp"

namespace parking {
namespace {

// string.Trim, for the ASCII white space a plate has.
std::string trim(const std::string& text) {
    const char* const space = " \t\n\v\f\r";
    const std::string::size_type first = text.find_first_not_of(space);
    if (first == std::string::npos) {
        return {};
    }
    const std::string::size_type last = text.find_last_not_of(space);
    return text.substr(first, last - first + 1);
}

// string.ToUpperInvariant, for ASCII.
std::string upper(std::string text) {
    for (char& c : text) {
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    }
    return text;
}

}  // namespace

Vehicle::Vehicle(const std::string& plate) : plate_(upper(trim(plate))) {
    if (plate_.empty()) {
        throw ccm::ArgumentException("A plate can't be empty.", "plate");
    }
}

ccm::Decimal Vehicle::size_factor() const { return 1; }

std::string Vehicle::to_string() const { return kind() + " " + plate_; }

Car::Car(const std::string& plate) : Vehicle(plate) {}

int Car::wheels() const { return 4; }

std::string Car::kind() const { return "car"; }

Motorcycle::Motorcycle(const std::string& plate) : Vehicle(plate) {}

int Motorcycle::wheels() const { return 2; }

std::string Motorcycle::kind() const { return "motorcycle"; }

ccm::Decimal Motorcycle::size_factor() const { return ccm::Decimal::parse("0.5"); }

}  // namespace parking

