namespace Parking
{
    /// <summary>A vehicle, known by its plate.</summary>
    public abstract class Vehicle
    {
        internal readonly parking_VehicleHandle Handle;

        protected Vehicle(string plate)
            : this(Unported(plate))
        {
        }

        internal Vehicle(parking_VehicleHandle handle)
        {
            Handle = handle;
        }

        /// <summary>The plate, trimmed and in upper case.</summary>
        public string Plate
        {
            get
            {
                IntPtr result;
                CcmInterop.Check(CcmNative.parking_Vehicle_plate(Handle, out result));
                return CcmInterop.TakeString(result);
            }
        }

        public abstract int Wheels { get; }

        public abstract string Kind { get; }

        /// <summary>How much of a car's place it takes: fees scale with it.</summary>
        public virtual decimal SizeFactor
        {
            get
            {
                CcmDecimal result;
                CcmInterop.Check(CcmNative.parking_Vehicle_size_factor(Handle, out result));
                return result.ToDecimal();
            }
        }

        public override string ToString()
        {
            IntPtr result;
            CcmInterop.Check(CcmNative.parking_Vehicle_to_string(Handle, out result));
            return CcmInterop.TakeString(result);
        }

        internal static Vehicle FromHandle(parking_VehicleHandle handle)
        {
            return CcmObjects.Wrap(handle, h => Create(h));
        }

        internal static parking_VehicleHandle HandleOf(Vehicle vehicle)
        {
            return vehicle == null ? parking_VehicleHandle.Null : vehicle.Handle;
        }

        private static Vehicle Create(parking_VehicleHandle handle)
        {
            int kind;
            CcmInterop.Check(CcmNative.parking_Vehicle_class(handle, out kind));
            switch (kind)
            {
                case 1:
                    return new Car(handle);
                case 2:
                    return new Motorcycle(handle);
                default:
                    throw new InvalidOperationException("The C++ vehicle has no C# class.");
            }
        }

        // The subclasses are C++ too, with the hierarchy: a C# subclass would have no C++ to run.
        private static parking_VehicleHandle Unported(string plate)
        {
            throw new NotSupportedException(
                "Parking.Vehicle is C++ now: only Car and Motorcycle derive from it (CodeCoreMorph, D-78).");
        }
    }
}

