namespace bridge = ccm::bridge;

namespace {

// A C# Money's field, which the C# constructor checked.
parking::Money money(ccm_decimal amount) { return parking::Money(bridge::dec(amount)); }

}  // namespace

extern "C" {

ccm_status parking_Money_new(ccm_decimal amount, ccm_decimal* result_amount) {
    return bridge::guard([&] { *result_amount = bridge::dec(money(amount).amount()); });
}

ccm_status parking_Money_add(ccm_decimal a_amount, ccm_decimal b_amount,
                             ccm_decimal* result_amount) {
    return bridge::guard(
        [&] { *result_amount = bridge::dec((money(a_amount) + money(b_amount)).amount()); });
}

ccm_status parking_Money_times(ccm_decimal a_amount, int32_t times, ccm_decimal* result_amount) {
    return bridge::guard([&] { *result_amount = bridge::dec((money(a_amount) * times).amount()); });
}

ccm_status parking_Money_scale(ccm_decimal a_amount, ccm_decimal factor,
                               ccm_decimal* result_amount) {
    return bridge::guard([&] {
        *result_amount = bridge::dec((money(a_amount) * bridge::dec(factor)).amount());
    });
}

ccm_status parking_Money_equals(ccm_decimal a_amount, ccm_decimal b_amount, bool* result) {
    return bridge::guard([&] { *result = money(a_amount) == money(b_amount); });
}

ccm_status parking_Money_min(ccm_decimal a_amount, ccm_decimal b_amount,
                             ccm_decimal* result_amount) {
    return bridge::guard([&] {
        *result_amount = bridge::dec(parking::Money::min(money(a_amount), money(b_amount)).amount());
    });
}

ccm_status parking_Money_hash_code(ccm_decimal amount, int32_t* result) {
    return bridge::guard([&] {
        const std::size_t hash = money(amount).hash();
        // GetHashCode is an int: the hash's low and high halves, folded.
        *result = static_cast<int32_t>(static_cast<uint32_t>(hash ^ (hash >> 32U)));
    });
}

ccm_status parking_Money_to_string(ccm_decimal amount, char** result) {
    return bridge::guard([&] { bridge::out_str(result, money(amount).to_string()); });
}

}  // extern "C"

