// The C++ of Parking.Money, ported from C# (CodeCoreMorph, D-78).
#include "money.hpp"

#include <string>

#include "codecoremorph_exceptions.hpp"
#include "limits.hpp"

namespace parking {

Money::Money(const ccm::Decimal& amount) : amount_(amount) {
    if (amount_ < 0) {
        throw ccm::ArgumentOutOfRangeException("amount", "Money can't be negative.");
    }
}

Money Money::min(const Money& a, const Money& b) { return a.amount_ <= b.amount_ ? a : b; }

std::string Money::to_string() const {
    // decimal.ToString("0.00", CultureInfo.InvariantCulture): two places, half away from zero.
    std::string text = round(amount_, 2, true).to_string();
    const std::string::size_type point = text.find('.');
    if (point == std::string::npos) {
        text += ".00";
    } else if (text.size() - point == 2) {
        text += '0';
    }
    return text + " " + std::string(limits::currency);
}

Money operator+(const Money& a, const Money& b) { return Money(a.amount_ + b.amount_); }

Money operator*(const Money& a, int times) { return Money(a.amount_ * times); }

Money operator*(const Money& a, const ccm::Decimal& factor) { return Money(a.amount_ * factor); }

}  // namespace parking

