    internal interface INativeRatePlan
    {
        parking_IRatePlanHandle RatePlanHandle();
    }

    /// <summary>IRatePlan across the bridge: a C++ implementation's own object, or a C#
    /// implementation (a test double) behind a native proxy that calls back into it.</summary>
    internal static class IRatePlanBridge
    {
        private static readonly parking_IRatePlan_name_fn NameThunk = Name;
        private static readonly parking_IRatePlan_charge_fn ChargeThunk = Charge;

        internal static parking_IRatePlanHandle HandleOf(IRatePlan plan)
        {
            if (plan == null)
            {
                return parking_IRatePlanHandle.Null;
            }
            var native = plan as INativeRatePlan;
            if (native != null)
            {
                return native.RatePlanHandle();
            }
            parking_IRatePlanHandle handle;
            CcmInterop.Check(CcmNative.parking_IRatePlan_from_managed(
                CcmInterop.Pin(plan), CcmInterop.Release, NameThunk, ChargeThunk, out handle));
            return handle;
        }

        /// <summary>The C# object of a plan that came back from the C++: the C# implementation
        /// behind a proxy, else the façade of the C++ one (kept alive by what gave it out).</summary>
        internal static IRatePlan FromHandle(parking_IRatePlanHandle handle)
        {
            if (handle.IsInvalid)
            {
                return null;
            }
            IntPtr managed;
            CcmInterop.Check(CcmNative.parking_IRatePlan_managed(handle, out managed));
            if (managed != IntPtr.Zero)
            {
                handle.Dispose();
                return CcmInterop.Target<IRatePlan>(managed);
            }
            return CcmObjects.Wrap<IRatePlan, parking_IRatePlanHandle>(handle, h =>
            {
                throw new InvalidOperationException("The C++ rate plan has no C# façade.");
            });
        }

        private static int Name(IntPtr context, out IntPtr result)
        {
            string name;
            int status = CcmInterop.Callback(() => CcmInterop.Target<IRatePlan>(context).Name, out name);
            result = status == 0 ? CcmInterop.NewString(name) : IntPtr.Zero;
            return status;
        }

        private static int Charge(IntPtr context, IntPtr vehicle, int minutes, out CcmDecimal result_amount)
        {
