    const int days = minutes / limits::minutes_per_day;
    const int rest = minutes % limits::minutes_per_day;
    const int hours = (rest + limits::minutes_per_hour - 1) / limits::minutes_per_hour;
    const Money total = daily_cap_ * days + Money::min(per_hour_ * hours, daily_cap_);
    return total * vehicle->size_factor();
}

