#ifndef PARKING_TALLY_HPP
#define PARKING_TALLY_HPP

#include <cstddef>
#include <cstdint>
#include <limits>
#include <unordered_map>
#include <vector>

#include "codecoremorph_exceptions.hpp"

namespace parking {

// Counts how often each item was seen. C#'s Dictionary enumerates in the order the items were
// first seen (nothing is ever removed), and MostCommon depends on it: the counts are kept in that
// order, with an index beside them.
template <class T>
class Tally {
public:
    void add(const T& item) {
        const auto found = index_.find(item);
        if (found == index_.end()) {
            index_.emplace(item, entries_.size());
            entries_.push_back(Entry{item, 1});
        } else {
            ++entries_[found->second].count;
        }
    }

    // How often the item was seen: 0 for one never seen.
    int operator[](const T& item) const {
        const auto found = index_.find(item);
        return found == index_.end() ? 0 : entries_[found->second].count;
    }

    // The number of different items.
    int count() const { return static_cast<int>(entries_.size()); }

    // Enumerable.Sum checks for overflow: so does this.
    int total() const {
        std::int64_t sum = 0;
        for (const Entry& entry : entries_) {
            sum += entry.count;
            if (sum > std::numeric_limits<int>::max()) {
                throw ccm::OverflowException("Arithmetic operation resulted in an overflow.");
            }
        }
        return static_cast<int>(sum);
    }

    // The item seen most often; of those tied, the first one seen.
    const T& most_common() const {
        if (entries_.empty()) {
            throw ccm::InvalidOperationException("The tally is empty.");
        }
        const Entry* best = &entries_.front();
        for (const Entry& entry : entries_) {
            if (entry.count > best->count) {
                best = &entry;
            }
        }
        return best->item;
    }

private:
    struct Entry {
        T item;
        int count;
    };

    std::vector<Entry> entries_;
    std::unordered_map<T, std::size_t> index_;
};

}  // namespace parking

