// plate.Trim().ToUpperInvariant(), for ASCII.
std::string key(const std::string& plate) {
    const char* const space = " \t\n\v\f\r";
    const std::string::size_type first = plate.find_first_not_of(space);
    if (first == std::string::npos) {
        return {};
    }
    std::string text = plate.substr(first, plate.find_last_not_of(space) - first + 1);
    for (char& c : text) {
