    if (capacity < 1 || capacity > limits::max_capacity) {
        throw ccm::ArgumentOutOfRangeException(
            "capacity", "A garage has 1 to " + std::to_string(limits::max_capacity) + " places.");
    }
    if (!plan_) {
        throw ccm::ArgumentNullException("plan");
    }
}

int Garage::subscribe_vehicle_left(VehicleLeftHandler handler) {
    const int token = next_token_++;
    vehicle_left_.emplace_back(token, std::move(handler));
    return token;
}

void Garage::unsubscribe_vehicle_left(int token) noexcept {
    vehicle_left_.erase(std::remove_if(vehicle_left_.begin(), vehicle_left_.end(),
                                       [token](const auto& entry) { return entry.first == token; }),
                        vehicle_left_.end());
}

const std::shared_ptr<Vehicle>& Garage::operator[](const std::string& plate) const {
    const std::string wanted = key(plate);
    for (const std::shared_ptr<Vehicle>& vehicle : parked_) {
        if (vehicle->plate() == wanted) {
            return vehicle;
        }
    }
    throw ccm::KeyNotFoundException("No vehicle " + wanted + " is parked.");
}

void Garage::enter(const std::shared_ptr<Vehicle>& vehicle, int minute) {
    if (!vehicle) {
        throw ccm::ArgumentNullException("vehicle");
    }
    if (minute < 0) {
        throw ccm::ArgumentOutOfRangeException("minute", "Time starts at minute 0.");
    }
    if (entered_.count(vehicle->plate()) != 0) {
        throw ccm::InvalidOperationException(vehicle->plate() + " is parked already.");
    }
    if (count() == capacity_) {
        throw GarageFullException(capacity_);
    }
    parked_.push_back(vehicle);
    entered_.emplace(vehicle->plate(), minute);
    visits_.add(vehicle->plate());
    hours_.add(minute / limits::minutes_per_hour % 24);
}

Money Garage::leave(const std::string& plate, int minute) {
    const std::shared_ptr<Vehicle> vehicle = (*this)[plate];
    const int since = entered_.at(vehicle->plate());
    if (minute < since) {
        throw ccm::ArgumentOutOfRangeException("minute", "A vehicle can't leave before it came.");
    }
    const Money fee = plan_->charge(vehicle, minute - since);
    parked_.erase(std::find(parked_.begin(), parked_.end(), vehicle));
    entered_.erase(vehicle->plate());
    takings_ = takings_ + fee;
    // As a C# event: the subscribers when it was raised, in the order they came.
    const std::vector<std::pair<int, VehicleLeftHandler>> subscribers = vehicle_left_;
    for (const auto& subscriber : subscribers) {
        subscriber.second(vehicle->plate(), fee);
    }
    return fee;
}

int Garage::visits_of(const std::string& plate) const { return visits_[key(plate)]; }

int Garage::busiest_hour() const { return hours_.most_common(); }

int Garage::count_where(
    const std::function<bool(const std::shared_ptr<Vehicle>&)>& predicate) const {
    if (!predicate) {
        throw ccm::ArgumentNullException("predicate");
    }
    return static_cast<int>(std::count_if(parked_.begin(), parked_.end(), predicate));
}

std::vector<std::string> Garage::plates() const {
    std::vector<std::string> found;
    found.reserve(parked_.size());
    for (const std::shared_ptr<Vehicle>& vehicle : parked_) {
        found.push_back(vehicle->plate());
    }
    // StringComparer.Ordinal: by UTF-16 code unit in C#, by byte here; the same for ASCII.
    std::sort(found.begin(), found.end());
    return found;
}

