    public sealed class Garage
    {
        private static readonly parking_Garage_vehicle_left_fn VehicleLeftThunk = OnVehicleLeft;

        internal readonly parking_GarageHandle Handle;

        // Keeps the façade of a C++ plan alive, so Plan gives the same object back.
        private readonly IRatePlan plan;
        private readonly object gate = new object();
        private Action<string, Money> vehicleLeft;
        private int vehicleLeftToken = -1;

        public Garage(int capacity, IRatePlan plan)
        {
            parking_GarageHandle handle;
            using (parking_IRatePlanHandle planHandle = IRatePlanBridge.HandleOf(plan))
            {
                CcmInterop.Check(CcmNative.parking_Garage_new(capacity, planHandle, out handle));
            }
            Handle = handle;
            this.plan = plan;
            CcmObjects.Register(handle.Key, this);
        }

        /// <summary>Raised after a vehicle left, with its plate and its fee.</summary>
        public event Action<string, Money> VehicleLeft
        {
            add
            {
                lock (gate)
                {
                    if (value == null)
                    {
                        return;
                    }
                    if (vehicleLeft == null)
                    {
                        CcmInterop.Check(CcmNative.parking_Garage_subscribe_vehicle_left(
                            Handle, CcmInterop.Pin(this), CcmInterop.Release, VehicleLeftThunk, out vehicleLeftToken));
                    }
                    vehicleLeft += value;
                }
            }
            remove
            {
                lock (gate)
                {
                    vehicleLeft -= value;
                    if (vehicleLeft == null && vehicleLeftToken >= 0)
                    {
                        CcmInterop.Check(CcmNative.parking_Garage_unsubscribe_vehicle_left(Handle, vehicleLeftToken));
                        vehicleLeftToken = -1;
                    }
                }
            }
        }

