            CcmInterop.Check(CcmNative.parking_Garage_busiest_hour(Handle, out result));
            return result;
        }

        public int CountWhere(Func<Vehicle, bool> predicate)
        {
            parking_Garage_count_where_fn call = null;
            if (predicate != null)
            {
                call = (IntPtr context, IntPtr vehicle, out bool result) =>
                {
                    var vehicleHandle = new parking_VehicleHandle(vehicle);
                    return CcmInterop.Callback(() => predicate(Vehicle.FromHandle(vehicleHandle)), out result);
