// Parking.Cli KIND:PLATE:MINUTES...: parks each vehicle at minute 0, lets each leave after its
// minutes on the hourly plan, and prints each fee and the takings.
int parking_cli_main(const std::vector<std::string>& args) {
    using namespace parking;
    if (args.empty()) {
        std::cerr << "usage: Parking.Cli KIND:PLATE:MINUTES...\n";
        return 2;
    }
    Garage garage(limits::max_capacity,
                  std::make_shared<HourlyRate>(Money(ccm::Decimal::parse("2.50")), Money(20)));
    std::vector<std::pair<std::string, int>> stays;
    try {
        for (const std::string& arg : args) {
            const std::vector<std::string> parts = cli::split(arg, ':');
            int minutes = 0;
            if (parts.size() != 3 || !cli::try_parse(parts[2], minutes)) {
                std::cerr << "not KIND:PLATE:MINUTES: " << arg << '\n';
                return 2;
            }
            const std::shared_ptr<Vehicle> vehicle = cli::make(parts[0], parts[1]);
            if (!vehicle) {
                std::cerr << "no such kind of vehicle: " << parts[0] << '\n';
                return 2;
            }
            garage.enter(vehicle, 0);
            stays.emplace_back(vehicle->plate(), minutes);
        }
        for (const auto& [plate, minutes] : stays) {
            const Money fee = garage.leave(plate, minutes);
            std::cout << plate << " paid " << fee.to_string() << '\n';
        }
    } catch (const ccm::ArgumentException& e) {
        std::cerr << cli::message(e) << '\n';
        return 1;
    } catch (const ccm::InvalidOperationException& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
    std::cout << "takings " << garage.takings().to_string() << '\n';
    return 0;
}

