// NUnit's Assert.Throws<E> for the tests translated from C# (CodeCoreMorph, D-78): a copy of what
// f throws when it is exactly an E, as Assert.Throws wants it; null otherwise.
#ifndef PARKING_TESTS_THROWN_HPP
#define PARKING_TESTS_THROWN_HPP

#include <memory>
#include <typeinfo>

namespace parking::tests {

template <class E, class F>
std::shared_ptr<const E> thrown(F f) {
    try {
        f();
    } catch (const E& e) {
        if (typeid(e) == typeid(E)) {
            return std::make_shared<const E>(e);
        }
        return nullptr;
    } catch (...) {
        return nullptr;
    }
    return nullptr;
}

}  // namespace parking::tests

#endif

