TEST(VehicleTests, ACarHasFourWheels) {
    const std::shared_ptr<Vehicle> car = std::make_shared<Car>("ab-123");
    EXPECT_EQ(4, car->wheels());
    EXPECT_EQ("car", car->kind());
    EXPECT_EQ(ccm::Decimal(1), car->size_factor());
