TEST(VehicleTests, AMotorcycleTakesHalfAPlace) {
    const std::shared_ptr<Vehicle> motorcycle = std::make_shared<Motorcycle>("m-1");
    EXPECT_EQ(2, motorcycle->wheels());
    EXPECT_EQ("motorcycle", motorcycle->kind());
    EXPECT_EQ(ccm::Decimal::parse("0.5"), motorcycle->size_factor());
}

