    EXPECT_EQ("XY 9", Car("  xy 9 ").plate());
}

TEST(VehicleTests, ABlankPlateIsRefused) {
    const auto e = thrown<ccm::ArgumentException>([] { (void)Motorcycle("   "); });
    ASSERT_NE(nullptr, e);
    EXPECT_EQ("plate", e->param_name());
}

TEST(VehicleTests, ToStringNamesTheKindAndThePlate) {
